START TRANSACTION;

DELETE FROM orders WHERE status = 'cancelled';
SELECT COUNT(*) FROM orders;

ROLLBACK;
SELECT COUNT(*) FROM orders;

START TRANSACTION;
UPDATE coffees SET price = 99 WHERE id = 1;
SAVEPOINT before_stock;
UPDATE coffees SET stock = 0 WHERE id = 1;
ROLLBACK TO before_stock;
SELECT price, stock FROM coffees WHERE id = 1;
ROLLBACK;

START TRANSACTION;

SELECT stock FROM coffees WHERE id = 1 FOR UPDATE;

UPDATE coffees SET stock = stock - 2 WHERE id = 1;

INSERT INTO orders (customer_id, coffee_id, quantity, status)
VALUES (5, 1, 2, 'paid');

COMMIT;
